import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.*

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    val containers = MutableList(m) { Pair(0, 0) }
    for (i in 0 until m) {
        val a = scanner.nextInt()
        val b = scanner.nextInt()
        containers[i] = a to b
    }

    containers.sortBy { it.second }

    var remaining = n
    var sum: Long = 0
    for (i in m - 1 downTo 0) {
        val (a, b) = containers[i]
        if (a < remaining) {
            sum += a.toLong() * b
            remaining -= a
        } else {
            sum += remaining.toLong() * b
            break
        }
    }

    println(sum)
}

class FastScanner(private val reader: BufferedReader = BufferedReader(InputStreamReader(System.`in`), 1024 * 10)) {
    private var buffer: String? = null
    private var index = 0

    private fun readBuffer(): Boolean {
        buffer = reader.readLine()
        index = 0
        return buffer != null
    }

    fun nextInt(): Int {
        var c: Int
        var sign = 1
        var res = 0

        // Skip non-digit characters
        while (true) {
            if (index >= buffer?.length!!) {
                if (!readBuffer()) return res
            }
            c = buffer!![index].code
            if (c == '-'.code) {
                sign = -1
                index++
                break
            }
            if (c >= '0'.code && c <= '9'.code) break
            index++
        }

        // Read number
        while (true) {
            if (index >= buffer!!.length) {
                if (!readBuffer()) return res * sign
            }
            c = buffer!![index].code
            if (c < '0'.code || c > '9'.code) {
                index++
                return res * sign
            }
            res = res * 10 + (c - '0'.code)
            index++
        }
    }
}

import java.io.BufferedOutputStream
import java.io.InputStream
import java.io.OutputStream
import java.util.Arrays

fun main() {
    val scanner = FastScanner(System.`in`)
    val out = BufferedOutputStream(System.`out`)

    val n = scanner.nextInt()
    val m = scanner.nextInt()

    val a = IntArray(m)
    val b = IntArray(m)
    for (i in 0 until m) {
        a[i] = scanner.nextInt()
        b[i] = scanner.nextInt()
    }

    // Sort by b ascending, keeping a in sync.
    // Create indices array to sort both arrays based on b.
    val indices = IntArray(m) { it }
    Arrays.sort(indices) { i, j -> b[i] - b[j] }

    var capacity = n
    var sum = 0L

    for (idx in indices.reversed()) {
        val matches = a[idx]
        val value = b[idx]
        if (matches < capacity) {
            sum += matches.toLong() * value
            capacity -= matches
        } else {
            sum += capacity.toLong() * value
            break
        }
    }

    out.write("$sum\n".toByteArray())
    out.flush()
